j:jelly.script:
function openFieldPickerSourceField(entity) {
	var referenceEntityTable = entity.table;
	var entityTable = g_form.getValue("table");
	var relationTypeValue = g_form.getValue("relation_type") || "";
	var relationTypeDisplayValue = g_form.getOption('relation_type', relationTypeValue).text;
	var currentFieldValue = g_form.getValue("source_field") || "";
	var parentEntitySource = entity.source_type;
	var childEntitySource = g_form.getValue("source_type");

	var gm = new GlideModal('po_entity_relationship_picker');
	gm.setTitle(getMessage("Select related field")); 
	gm.setPreference('sysparm_referenceEntityTable', referenceEntityTable);
	gm.setPreference('sysparm_entityTable', entityTable); 	
	gm.setPreference('sysparm_relationType', relationTypeValue);
	gm.setPreference('sysparm_currentFieldValue', currentFieldValue);
	gm.setPreference('sysparm_parentEntitySource', parentEntitySource);
	gm.setPreference('sysparm_childEntitySource', childEntitySource);
	gm.setPreference('focusTrap', true);
	gm.setWidth(550);
	gm.render();
}

function openTableSourceFieldPicker(){
	g_form.getReference('parent_entity', openFieldPickerSourceField);
}
